function configureFilters(){const keys=viewFilterKeys[currentView];$('.advanced-filters').hidden=!keys.includes('rank')&&!keys.includes('opening');const visible=keys.length>0;$('.filters').hidden=!visible;$('.search-surface').hidden=!keys.includes('query');$('.workspace').classList.toggle('sources-view',!visible);for(const [id,key] of [['institution','institution'],['rank','rank'],['topic','topic'],['opportunity','opportunityType'],['opening','opening']])$('#'+id+'-filter-label').hidden=!keys.includes(key);$('#rank-filter-note').hidden=!keys.includes('rank');$('#opportunity-filter-note').hidden=currentView!=='advisors';$('#opening-filter-note').hidden=!keys.includes('opening');$('#filter-title').textContent={advisors:'筛选导师',routes:'筛选项目',deadlines:'筛选学校',materials:'筛选材料'}[currentView]||'筛选';$('#opportunity-filter-name').textContent=currentView==='materials'?'适用学位':currentView==='routes'?'学位类型':'申请类型';const labels={RA:'RA · 研究助理',MSc:'MSc · 理学硕士',MPhil:'MPhil · 研究型硕士',PhD:'PhD · 博士'};const types=currentView==='advisors'?['RA','MSc','MPhil','PhD']:['MSc','MPhil','PhD'];$('#opportunity-filter').innerHTML=`<option value="">${currentView==='advisors'?'全部申请类型':'全部学位'}</option>`+types.map(value=>`<option value="${value}">${labels[value]}</option>`).join('');$('#opportunity-filter').value=state.opportunityType;$('#search').placeholder={advisors:'搜索导师、学校或研究方向…',routes:'搜索项目名称、研究方向或申请条件…',materials:'搜索材料名称或要求…'}[currentView]||'';$('#search-label').textContent={advisors:'搜索导师、学校或研究方向',routes:'搜索项目名称、研究方向或申请条件',materials:'搜索材料名称或要求'}[currentView]||'搜索';updateFilterLabels();}
