function switchView(view){const previousExperience=currentView==='experiences'?activeExperienceId:null;++experienceRestoreSerial;experienceRestoring=false;if($('#detail-dialog').open)$('#detail-dialog').close();const base=view.split('/')[0];currentView=Object.hasOwn(viewLabels,base)?base:'advisors';activeExperienceId=null;if(currentView==='experiences'&&view.startsWith('experiences/')){try{activeExperienceId=decodeURIComponent(view.slice('experiences/'.length));}catch{activeExperienceId='invalid-experience-link';}}state=filterStates[currentView];if(currentView==='experiences'&&activeExperienceId===null){const entry=window.history?.state;const saved=experiencePositions.get(entry?.gradExperienceKey)||entry?.gradExperiencePosition;if(saved?.filters)Object.assign(experienceFilters,saved.filters);}syncFilterValues();render();if(currentView==='experiences')restoreExperiencePosition(previousExperience);else activeExperienceEntryKey=null;}
