function handleProjectComparison(evt){const add=evt.target.closest('[data-compare-project]');if(add){selectProjectCompare(add.dataset.compareProject);return true;}const remove=evt.target.closest('[data-remove-project]');if(remove){const removedIndex=projectCompareIds.indexOf(remove.dataset.removeProject);projectCompareIds=projectCompareIds.filter(id=>id!==remove.dataset.removeProject);updateTray();if(projectCompareIds.length<2){dismissComparison();}else{window.history?.replaceState?.({...window.history.state},'','#routes/compare/'+projectCompareIds.map(encodeURIComponent).join(','));openProjectCompare(true,removedIndex>=0?'remove:'+projectCompareIds[Math.min(removedIndex,projectCompareIds.length-1)]:null);}return true;}if(evt.target.closest('[data-project-differences]')){projectDifferencesOnly=!projectDifferencesOnly;openProjectCompare(true);$('#compare-content').querySelector?.('[data-project-differences]')?.focus();return true;}return false;}
function selectCompare(id){const next=toggleCompare(compareIds,id);if(next===compareIds){showNotice('最多同时比较 3 条机会，先移除一项即可');return;}compareIds=next;updateTray();}
function selectedRaStatement(job){return `当前岗位 #${job.jobReference} 的本科任职条件与公开招募已核实；其他 RA 声明仍需逐岗位核实`; }
function openingRows(a,selectedJob=null){const o=a.openings||{};const verifiedRa=buildOpportunities(catalog).some(x=>x.advisorId===a.id&&x.type==='RA');return [['MSc',o.msc??o.MSc],['MPhil',o.mphil??o.MPhil],['PhD',o.phd??o.PhD],['RA',selectedJob?selectedRaStatement(selectedJob):`${readerText(o.ra??o.RA)||'未核实公开招募'}${verifiedRa?'；具体任职条件见对应岗位':'；本科任职条件待核实'}`],['2027 Fall',o.cycle2027??o['2027_fall_specific']]].map(([k,v])=>`<dt>${e(k)}</dt><dd>${e(textValue(v)||'未找到可核实的公开声明')}</dd>`).join('');}
function detailRoute(r){return `<section class="evidence-box"><h4>${e(institutionLabel(r.institution))} · ${e(r.program||r.degree)}</h4><p>${e(r.eligibilitySummary)}</p>${r.supervisorAssociation?`<p class="small-note">${e(supervisorAssociationText(r.supervisorAssociation))}</p>`:''}${requirementsList(r.requirements)}<div class="link-list">${sourceLinks(r.sources)}</div></section>`;}
function openDetail(id,replay=false){const opportunity=buildOpportunities(catalog).find(o=>o.id===id);const a=catalog.advisors.find(a=>a.id===(opportunity?.advisorId||id));if(!a){if(replay)showMissingDetail('advisor');return;}if(!replay)pushDetailRoute('advisor',id);updateDetailBack();$('#detail-kind').textContent='导师与申请信息';activeDetail=id;const rs=opportunity?catalog.routes.filter(r=>r.id===opportunity.routeId):routesFor(a,catalog).filter(isVerifiedRoute);const job=(catalog.raPositions||[]).find(j=>j.id===opportunity?.jobId);const extraAssociations=(a.routeAssociations||[]).filter(x=>x.status!=='verified');$('#detail-content').innerHTML=`<h2 id="detail-title" class="detail-title" tabindex="-1">${job?e(job.title||"研究助理 RA"):aName(a)}</h2>${job?`<p class="detail-subtitle">${aName(a)} · RA 工作岗位</p>`:""}${opportunity?`<div class="opportunity-context">${e(opportunity.type)} · ${e(rs[0]?.program||job?.title||'研究助理岗位')}</div>`:''}<p class="detail-subtitle">${e(institutionLabel(a.institution))} · ${e(a.department)}<br>${e(a.position)}${a.lab?` · ${e(a.lab)}`:''}</p><div class="status-group">${a.newPi?.verified?badge('new','新入职已核实'):''}</div><div class="link-list">${link(a.profileUrl,'学校 / 官方档案')}${link(a.labUrl,'课题组 / 个人主页')}</div>${a.email?`<p class="small-note">公开业务邮箱：${e(a.email)}（申请联系偏好以官网为准）</p>`:''}${advisorProfiles.has(a.id)?renderProfile(advisorProfiles.get(a.id)):`<p class="profile-pending small-note">专业简介待补充；以下保留已核实的研究方向与代表工作</p><section class="detail-section"><h3>研究方向与代表工作</h3><p>${e(a.summary)}</p><div class="tags detail-tags">${publicTags(a)}</div>${(a.works||[]).map(w=>`<div class="evidence-box"><h4>${e(w.title)} ${w.year?`<span class="quiet">${e(w.year)}</span>`:''}</h4>${w.note||w.evidence?`<p>${e(w.note||w.evidence)}</p>`:''}<div class="link-list">${link(w.url,'作者项目 / 原始论文')}</div></div>`).join('')}</section>`}<section class="detail-section"><h3>${job?'岗位任职条件':'申请路径与条件'}</h3><p class="small-note">${job?'RA 为受雇科研岗位，不授予学位录取资格。':'项目允许本科起点，普通申请不强制推免，也不要求已有硕士。个人成绩、英语、毕业时间与导师接收意向仍需满足。'}</p>${job?employmentDetail(job):rs.length?rs.map(detailRoute).join(''):'<div class="caution-box"><p>申请路径或导师关联仍待核实</p></div>'}${extraAssociations.length?`<div class="caution-box"><p><strong>其他路径与关联限制</strong></p><ul>${extraAssociations.map(x=>`<li>${e([x.degree,x.reason,x.summary,x.note,x.association,x.pi_program_association].filter(Boolean).map(readerText).join('；')||textValue(x))}</li>`).join('')}</ul></div>`:''}</section><section class="detail-section"><h3>招生与招聘 · 按申请类型分开</h3><dl class="fact-grid">${openingRows(a,job)}</dl><p class="small-note">${e(a.openingSummary||'未找到声明不等于不招生；未注明年份不能滚动视为 2027 Fall')}</p>${a.recruitmentReview?`<p class="small-note recruitment-review">招募复核于 ${e(a.recruitmentReview.checkedDate)}：${e(a.recruitmentReview.scope)}。其他信息沿用原核验日期。</p>`:''}<div class="link-list">${sourceLinks((a.openingDetails||[]).flatMap(o=>o.sources||[]).filter((s,i,arr)=>arr.findIndex(x=>x.url===s.url)===i))}</div></section>${a.newPi?.date||a.newPi?.note?`<section class="detail-section"><h3>任职时间</h3><p>${e(a.newPi.date||'准确入职日期未确认')} · ${e(a.newPi.note||'')}</p><div class="link-list">${sourceLinks(a.newPi.sources||[])}</div></section>`:''}${(a.caveats||[]).length?`<section class="caution-box"><ul>${a.caveats.map(c=>`<li>${e(c)}</li>`).join('')}</ul></section>`:''}${renderProfileReferences(advisorProfiles.get(a.id))}<section class="detail-section"><h3>证据来源</h3><p class="small-note">核验于 ${e(a.checkedDate||catalog.metadata.checkedDate)}。引用原文的判断范围以各项说明为准。</p><div class="link-list">${sourceLinks(a.sources)}</div></section>`;const advisorBody=$('#detail-content').innerHTML;$('#detail-content').innerHTML=`<div class="reading-layout"><article class="reading-main" data-reading-kind="${job?'ra':'advisor'}">${advisorBody}</article><aside class="reading-rail" aria-label="申请与来源"><section class="rail-panel"><h3>${job?'RA 岗位信息':'学位申请信息'}</h3><p>${job?'RA 是受雇科研岗位，不授予学位录取资格。':'学位资格、导师接收意向和当期剩余名额分别核对。'}</p><dl class="fact-grid">${openingRows(a,job)}</dl></section><section class="rail-panel"><h3>导师与团队</h3>${link(a.profileUrl,'查看导师主页 ↗')}${link(a.labUrl,'查看课题组主页 ↗')}<p class="small-note">核验于 ${e(a.checkedDate||catalog.metadata.checkedDate)}；完整证据和限制见正文。</p></section></aside></div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#active-filters').hidden=true;$('#detail-dialog').scrollTop=0;$('#detail-title')?.focus();}
function employmentDetail(job){const cr=job.currentRecruitment||{};return `<section class="evidence-box"><h4>${e(job.title||'研究助理')} · ${e(job.jobReference||'')}</h4><p>${e(job.employmentEligibility?.requirementText||job.requirementText||'官方岗位已明确接受本科，且不要求已有硕士')}</p><p class="small-note">${e(job.employmentEligibility?.interpretation||'具体学历等值由雇主审核')}</p>${job.duties?`<p>${e(job.duties)}</p>`:''}${job.duration?`<p>任期：${e(job.duration)}${job.workTime?.length?'；'+job.workTime.map(t=>t==='full-time'?'全职':t==='part-time'?'兼职':e(t)).join(' / '):''}</p>`:''}<p>公告：${e(job.noticeDate||'未注明')}；截止日期：${e(cr.deadline||'未公布')}；截止时刻：${e(cr.deadlineTime||'未公布')}</p><p class="small-note">${e(job.advisorAssociation?.detail||'')}</p><p class="small-note">岗位剩余额度与个人工作许可未核实；具体任职资格和到岗时间由雇主审核</p><ul>${(job.caveats||[]).map(c=>`<li>${e(c)}</li>`).join('')}</ul><div class="link-list">${sourceLinks(job.employmentEligibility?.sources||[])}</div></section>`;}
function openCompare(){if(currentView==='routes'){openProjectCompare();return;}if(compareIds.length<2)return;$('#compare-title').textContent='研究机会比较';const selected=compareIds.map(id=>buildOpportunities(catalog).find(o=>o.id===id)).filter(Boolean);$('#compare-content').innerHTML=`<p class="small-note">每列对应一条机会，同一导师的不同学位路径分别比较</p><div class="compare-grid columns-${selected.length}">${selected.map(o=>{const a=catalog.advisors.find(a=>a.id===o.advisorId);const r=catalog.routes.find(r=>r.id===o.routeId);const job=(catalog.raPositions||[]).find(j=>j.id===o.jobId);return `<article class="compare-column"><span class="opportunity-type">${e(o.type)}${job?.jobReference?' · #'+e(job.jobReference):''}</span><h3>${aName(a)}</h3><p>${e(institutionLabel(a.institution))}<br>${e(a.department)}</p><h4>研究主题</h4><div class="tags">${publicTags(a)}</div><p>${e(a.summary)}</p><h4>${job?'任职条件':'项目与申请条件'}</h4>${r?`<div class="evidence-box"><strong>${e(r.program)}</strong><p>${e(r.eligibilitySummary)}</p>${r.supervisorAssociation?`<p>${e(supervisorAssociationText(r.supervisorAssociation))}</p>`:''}<div class="link-list">${sourceLinks(r.sources,2)}</div></div>`:job?employmentDetail(job):'<p>条件待核实</p>'}<h4>该机会的公开招募</h4><p>${e(job?selectedRaStatement(job):readerText(a.openings?.[o.type.toLowerCase()])||'未核实公开声明')}</p><h4>其他类型招募与 2027 年份</h4><dl class="fact-grid">${openingRows(a,job)}</dl><h4>需要留意</h4><ul>${(a.caveats||[]).slice(0,4).map(c=>`<li>${e(c)}</li>`).join('')||'<li>个人资格与具体名额仍需核实</li>'}</ul><div class="link-list">${link(a.profileUrl,'官方档案')}</div></article>`;}).join('')}</div>`;if(!$('#compare-dialog').open)$('#compare-dialog').showModal();}
function updateFilterLabels(){const job=state.opportunityType==='RA';$('#opening-filter-name').textContent=job?'招聘信息':'招生信息';const labels=job?{explicit:'已发布岗位招聘',unknown:'招聘年份或名额待确认',closed:'已明确停止招聘'}:openLabel;$('#opening-filter').innerHTML=`<option value="">${job?'全部招聘信息':'全部招生信息'}</option>`+Object.entries(labels).map(([value,label])=>`<option value="${value}">${e(label)}</option>`).join('');$('#opening-filter').value=state.opening;}
function populateFilters(){const institutions=[...new Set([...catalog.advisors,...catalog.routes].map(a=>a.institution).filter(Boolean))];if(sustechReview?.advisors?.length)institutions.push(sustechInstitution);institutions.sort((a,b)=>displayInstitution(a).localeCompare(displayInstitution(b),'zh-CN'));$('#institution-filter').innerHTML='<option value="">全部学校</option>'+institutions.map(i=>`<option value="${e(i)}">${e(displayInstitution(i))}</option>`).join('');const topics=[...new Set(catalog.advisors.flatMap(themesFor))];$('#topic-filter').innerHTML='<option value="">全部研究方向</option>'+topics.map(t=>`<option value="${e(t)}">${e(t)}</option>`).join('');}
function bind(){bindExperienceTools();$('#menu-toggle').addEventListener('click',()=>{const expanded=$('#menu-toggle').getAttribute?.('aria-expanded')==='true';$('#menu-toggle').setAttribute('aria-expanded',String(!expanded));$('#menu-toggle').setAttribute('aria-label',expanded?'展开主导航':'收起主导航');if(expanded)$('.site-header').removeAttribute('data-menu-open');else $('.site-header').setAttribute('data-menu-open','');});for(const type of ['institution','topic','opportunity','opening','rank'])$(`#${type}-filter`).addEventListener('change',evt=>{const key=type==='opportunity'?'opportunityType':type;if(!viewFilterKeys[currentView].includes(key)){evt.target.value=state[key];return;}if(key==='opportunityType'&&!(currentView==='advisors'?['','RA','MSc','MPhil','PhD']:['','MSc','MPhil','PhD']).includes(evt.target.value)){evt.target.value=state[key];return;}state[key]=evt.target.value;render();});$('#search').addEventListener('input',evt=>{if(!viewFilterKeys[currentView].includes('query'))return;state.query=evt.target.value;render();});$('#reset-filters').addEventListener('click',reset);$('#active-filters').addEventListener('click',changeActiveFilter);$('#compare-clear').addEventListener('click',()=>{if(currentView==='routes')projectCompareIds=[];else compareIds=[];updateTray();});$('#compare-open').addEventListener('click',openCompare);document.addEventListener('click',evt=>{const readingSection=evt.target.closest('[data-reading-section]');if(readingSection){const target=document.getElementById(readingSection.dataset.readingSection);target?.focus?.({preventScroll:true});target?.scrollIntoView?.({block:'start'});return;}if(handleProjectComparison(evt))return;if(evt.target.closest('[data-view]')){if($('#menu-toggle').getAttribute?.('aria-expanded')==='true')$('#menu-toggle').focus({preventScroll:true});$('.site-header').removeAttribute('data-menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','展开主导航');}if(evt.target.closest('[data-find-results]')){evt.preventDefault();$('#results').focus?.({preventScroll:true});$('#results').scrollIntoView?.({block:'start'});return;}if(evt.target.closest('[data-experience-reset]')&&currentView==='experiences'&&activeExperienceId===null){Object.assign(experienceFilters,{query:'',collection:''});$('#experience-search').value='';$('#experience-collection').value='';refreshExperienceResults();$('#experience-search').focus({preventScroll:true});return;}if(evt.target.closest('[data-experience-find]')){$('#experience-search')?.focus({preventScroll:true});$('#experience-search')?.scrollIntoView({block:'center',behavior:'instant'});return;}if(navigateExperience(evt))return;const summary=evt.target.closest('[data-summary-kind]');if(summary)openSummary(summary.dataset.summaryKind,summary.dataset.summaryId);const detail=evt.target.closest('[data-detail]');if(detail)openDetail(detail.dataset.detail);const compare=evt.target.closest('[data-compare]');if(compare)selectCompare(compare.dataset.compare);const close=evt.target.closest('[data-close]');if(close){if(close.dataset.close==='detail-dialog')dismissDetail();else if(close.dataset.close==='compare-dialog')dismissComparison();else document.getElementById(close.dataset.close).close();}if(evt.target.closest('[data-reset]')){reset();focusVisibleFilter();}const quick=evt.target.closest('[data-overview-preset]');if(quick){const selection=overviewPresets[quick.dataset.overviewPreset];if(selection?.view===currentView){Object.assign(state,emptyFilters(),selection.filters);syncFilterValues();render();$('#view-content').focus?.({preventScroll:true});$('#view-content').scrollIntoView?.({block:'start'});}}const expand=evt.target.closest('[data-overview-expand]');if(expand?.dataset.overviewExpand==='experience-synthesis'){const details=$('#experience-synthesis');if(details){details.open=true;details.querySelector?.('summary')?.focus?.({preventScroll:true});details.scrollIntoView?.({block:'start'});}}const sw=evt.target.closest('[data-switch]');if(sw)location.hash=sw.dataset.switch;});document.addEventListener('keydown',evt=>{if(evt.key==='Escape'&&$('#menu-toggle').getAttribute?.('aria-expanded')==='true'){$('.site-header').removeAttribute('data-menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','展开主导航');$('#menu-toggle').focus();return;}if(evt.key==='/'&&currentView==='experiences'&&activeExperienceId===null&&!evt.ctrlKey&&!evt.metaKey&&!evt.altKey&&!document.activeElement?.isContentEditable&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')){evt.preventDefault();$('#experience-search')?.focus();return;}if(evt.key==='/'&&!$('.search-surface').hidden&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){evt.preventDefault();$('#search').focus();}});window.addEventListener('scroll',()=>saveExperiencePosition(null,false),{passive:true});window.addEventListener('hashchange',routeLocation);window.addEventListener('popstate',routeLocation);$('#detail-back').addEventListener('click',()=>{if(((window.history?.state?.gradDetailDepth||0)>1||((window.history?.state?.gradDetailDepth||0)>0&&window.history?.state?.gradDetailHasList===false))&&window.history?.back)window.history.back();else dismissDetail();});$('#compare-dialog').addEventListener('cancel',evt=>{evt.preventDefault();dismissComparison();});$('#detail-dialog').addEventListener('close',renderActiveFilters);$('#detail-dialog').addEventListener('cancel',evt=>{evt.preventDefault();dismissDetail();});for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',evt=>{if(evt.target===d){const r=d.getBoundingClientRect();if(evt.clientX<r.left||evt.clientX>r.right||evt.clientY<r.top||evt.clientY>r.bottom){if(d.id==='detail-dialog')dismissDetail();else if(d.id==='compare-dialog')dismissComparison();else d.close();}}});}
async function loadProjectSummaries(){try{const response=await fetch(new URL('../data/project-summaries.json?v=a901969671f4',import.meta.url));if(response.ok){const projectData=await response.json();const summaries=normalizeProjectSummaries(projectData,catalog);catalog={...catalog,projectSummaries:summaries};projectSummaryState=summaries.size===projectData.records.length?'loaded':'partial';}else{projectSummaryState='unavailable';}}catch{projectSummaryState='unavailable';}if(currentView==='routes')render();const route=parseDetailLocation();if(route?.kind==='project')openSummary(route.kind,route.id,true);if(parseCompareLocation())openProjectCompare(true);}
async function loadSustechReview(){try{const response=await fetch(new URL('../data/sustech-advisor-review-20261004.json?v=ec5204975321',import.meta.url));if(response.ok){const data=await response.json();if(data?.institution===sustechInstitution&&Array.isArray(data.advisors)){sustechReview=data;populateFilters();syncFilterValues();if(currentView==='advisors')render();}}}catch{}}
async function initialize(){try{const responses=await Promise.all(['catalog.json?v=3423ba646e7e','ra-positions.json','update-status.json'].map(name=>fetch(new URL('../data/'+name,import.meta.url))));if(responses.some(res=>!res.ok))throw Error('数据读取失败，请刷新重试');const [academicData,raData,statusData]=await Promise.all(responses.map(res=>res.json()));catalog={...academicData,raPositions:raData.raPositions||[]};updateStatus=statusData;try{const response=await fetch(new URL('../data/material-summaries.json?v=0e7779408d18',import.meta.url));if(response.ok){const materialData=await response.json();const supplement=normalizeMaterialSupplement(materialData,catalog);catalog={...catalog,materials:[...(catalog.materials||[]),...supplement]};materialSupplementState=supplement.length===materialData.records.length?'loaded':'partial';}}catch{}try{const response=await fetch(new URL('../data/application-experiences.json?v=3e46c7e8eea0',import.meta.url));if(response.ok)experienceRecords=normalizeExperiences(await response.json());}catch{}try{const response=await fetch(new URL('../data/advisor-profiles.json?v=1550cecabe98',import.meta.url));if(response.ok)advisorProfiles=profileMap(await response.json(),catalog.advisors);}catch{}if(!Array.isArray(catalog.advisors)||!Array.isArray(catalog.routes))throw Error('数据格式暂不可用');$('#checked-date').textContent=`核验于 ${catalog.metadata.checkedDate}`;$('.edition a').textContent=updateStatus.statusLabel;populateFilters();bind();switchView(parseDetailLocation()?.view||location.hash.slice(1)||'advisors');if(parseDetailLocation()||parseCompareLocation())routeLocation();void loadProjectSummaries();void loadSustechReview();}catch(err){$('#result-count').textContent='数据未能载入';$('#view-content').innerHTML=`<div class="empty"><h3>暂时无法读取数据</h3><p>${e(err.message)}</p><p>请刷新页面重试，或直接打开公开 JSON 查看已保存的记录</p><a class="source-link" href="./data/catalog.json">公开数据文件</a></div>`;}}
initialize();
